from functools import lru_cache

class Solution:
    def subtreeRemovalGame(self, n: int) -> bool:
        children = []
        def build(k):
            if k <= 0:
                return -1
            left = build(k - 2)
            me = len(children)
            children.append([left, -1])
            children[me][1] = build(k - 1)
            return me
        root = build(n)
        m = len(children)
        sub = [0] * m
        def collect(v):
            if v == -1:
                return 0
            sub[v] = (1 << v) | collect(children[v][0]) | collect(children[v][1])
            return sub[v]
        collect(root)
        full = ((1 << m) - 1) ^ (1 << root)

        @lru_cache(maxsize=None)
        def win(mask):
            s = mask
            while s:
                low = s & -s
                v = low.bit_length() - 1
                s ^= low
                if not win(mask & ~sub[v]):
                    return True
            return False

        return win(full)

