class Solution {
    vector<array<int, 2>> ch;
    vector<unsigned long long> sub;
    unordered_map<unsigned long long, char> memo;

    int build(int k) {
        if (k <= 0) return -1;
        int left = build(k - 2);
        int me = ch.size();
        ch.push_back({left, -1});
        ch[me][1] = build(k - 1);
        return me;
    }

    unsigned long long collect(int v) {
        if (v == -1) return 0;
        sub[v] = (1ULL << v) | collect(ch[v][0]) | collect(ch[v][1]);
        return sub[v];
    }

    bool win(unsigned long long mask) {
        auto it = memo.find(mask);
        if (it != memo.end()) return it->second;
        unsigned long long s = mask;
        while (s) {
            int v = __builtin_ctzll(s);
            s &= s - 1;
            if (!win(mask & ~sub[v])) { memo[mask] = 1; return true; }
        }
        memo[mask] = 0;
        return false;
    }

public:
    bool subtreeRemovalGame(int n) {
        ch.clear();
        int root = build(n);
        int m = ch.size();
        sub.assign(m, 0);
        collect(root);
        unsigned long long full = ((1ULL << m) - 1) & ~(1ULL << root);
        return win(full);
    }
};

