class Solution {
    private List<int[]> ch = new ArrayList<>();
    private long[] sub;
    private Map<Long, Boolean> memo = new HashMap<>();

    private int build(int k) {
        if (k <= 0) return -1;
        int left = build(k - 2);
        int me = ch.size();
        ch.add(new int[]{left, -1});
        int right = build(k - 1);
        ch.get(me)[1] = right;
        return me;
    }

    private long collect(int v) {
        if (v == -1) return 0;
        sub[v] = (1L << v) | collect(ch.get(v)[0]) | collect(ch.get(v)[1]);
        return sub[v];
    }

    private boolean win(long mask) {
        Boolean cached = memo.get(mask);
        if (cached != null) return cached;
        long s = mask;
        boolean res = false;
        while (s != 0) {
            int v = Long.numberOfTrailingZeros(s);
            s &= s - 1;
            if (!win(mask & ~sub[v])) { res = true; break; }
        }
        memo.put(mask, res);
        return res;
    }

    public boolean subtreeRemovalGame(int n) {
        ch.clear();
        int root = build(n);
        int m = ch.size();
        sub = new long[m];
        collect(root);
        long full = ((1L << m) - 1) & ~(1L << root);
        return win(full);
    }
}

