var subtreeRemovalGame = function(n) {
    const ch = [];
    const build = (k) => {
        if (k <= 0) return -1;
        const left = build(k - 2);
        const me = ch.length;
        ch.push([left, -1]);
        ch[me][1] = build(k - 1);
        return me;
    };
    const root = build(n);
    const m = ch.length;
    const sub = new Array(m).fill(0n);
    const collect = (v) => {
        if (v === -1) return 0n;
        sub[v] = (1n << BigInt(v)) | collect(ch[v][0]) | collect(ch[v][1]);
        return sub[v];
    };
    collect(root);
    const full = ((1n << BigInt(m)) - 1n) & ~(1n << BigInt(root));
    const memo = new Map();
    const win = (mask) => {
        if (memo.has(mask)) return memo.get(mask);
        let s = mask, res = false;
        while (s) {
            const low = s & -s;
            const v = low.toString(2).length - 1;
            s ^= low;
            if (!win(mask & ~sub[v])) { res = true; break; }
        }
        memo.set(mask, res);
        return res;
    };
    return win(full);
};

